                    int nr = zr + DR[k], nc = zc + DC[k];
                    if (is_cell_on_grid(nr, nc) &&
                        current_grid_state[nr][nc] != 0) {
                        pivot_color = current_grid_state[nr][nc];
                        break;
                    }
                }

                if (pivot_color != 0 &&
                    cells_by_color[pivot_color].size() >= 2) {
                    const auto& ward = cells_by_color[pivot_color];
                    std::pair<int,int> removed = {-1, -1};

                    int samples = std::min<int>(48, ward.size());
                    for (int s = 0; s < samples; ++s) {
                        const auto& p = ward[
                            rnd_gen.next_int(static_cast<int>(ward.size()))];
                        if (p.first == zr && p.second == zc) continue;

                        bool touches_zero = false;
                        for (int k = 0; k < 4; ++k) {
                            int nr = p.first + DR[k];
                            int nc = p.second + DC[k];
                            int neighbor = is_cell_on_grid(nr, nc)
                                ? current_grid_state[nr][nc] : 0;
                            if (neighbor == 0) {
                                touches_zero = true;
                                break;
                            }
                        }
                        if (touches_zero) {
                            removed = p;
                            break;
                        }
                    }

                    if (removed.first >= 0) {
